using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a message, if it is available without sending network request. Returns a 404 error if message isn't available locally. This is an offline method
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> GetMessageLocallyAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("GetMessageLocallyAsync", typeof(GetMessageLocally).FullName ?? "GetMessageLocallyAsync");

           try
           {
             return client.GetMessageLocallyAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
